import argparse
import json

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    user_max_ts = {}
    user_max_actions = {}

    with open(path, "r") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            user = event["user"]
            ts = event["ts"]
            action = event["action"]
            if user not in user_max_ts:
                user_max_ts[user] = ts
                user_max_actions[user] = {action}
            elif ts > user_max_ts[user]:
                user_max_ts[user] = ts
                user_max_actions[user] = {action}
            elif ts == user_max_ts[user]:
                user_max_actions[user].add(action)

    count = sum(1 for u in user_max_actions if "logout" in user_max_actions[u])
    print(count)

if __name__ == "__main__":
    main()

import argparse
import csv
import json
from datetime import date


def parse_date(value):
    value = value.strip()
    if not value:
        return None
    try:
        parts = value.split("-")
        if len(parts) != 3:
            return None
        return date(int(parts[0]), int(parts[1]), int(parts[2]))
    except (ValueError, IndexError):
        return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    with open(path, newline="") as f:
        rows = list(csv.reader(f))

    if not rows:
        print("0")
        return

    # Detect whether the first row is a header by trying to parse it as a date.
    first_cell = rows[0][0].strip() if rows[0] else ""
    if parse_date(first_cell) is not None:
        data_rows = rows
        date_col = 0
    else:
        header = rows[0]
        data_rows = rows[1:]
        date_col = 0
        for i, col in enumerate(header):
            if col.strip().lower() in ("date", "dates", "day", "datetime"):
                date_col = i
                break

    dates = []
    for row in data_rows:
        if not row or date_col >= len(row):
            continue
        d = parse_date(row[date_col])
        if d is not None:
            dates.append(d)

    if len(dates) < 2:
        print("0")
        return

    diff = (max(dates) - min(dates)).days
    print(diff)


if __name__ == "__main__":
    main()
